"""QQ-图像对比：在同一节点里叠加对比两张图（滑动 / 点击切换）。

预览逻辑与 rgthree 的 Image Comparer 一致：

* ``image_a`` / ``image_b`` 各自可以是单图或一批图；
* 滑动模式（Slide）：鼠标在节点上左右移动，B 图随光标位置揭开，露出下面的 A 图；
* 点击模式（Click）：点一下在 A / B 之间切换；
* 任一侧是多张时，节点顶部出现 A1/A2/B1/B2 标签，点选要对比的那两张。

与原版的关键区别：原版用 LiteGraph 的画布控件（``addCustomWidget`` + ``draw``）绘制，
这种控件在 ComfyUI 新版「Nodes 2.0」（Vue 渲染）里不显示。本节点的前端改用
``addDOMWidget``（HTML 元素），它在 1.0 和 2.0 两种渲染下都能正常工作。
后端只负责把两侧图片存成临时预览并上报 ``a_images`` / ``b_images``。
"""

from __future__ import annotations

from typing import Any

try:
    from nodes import PreviewImage
except Exception:  # 测试桩 / 异常环境缺 PreviewImage 时退回最小基类，保证整个包仍能导入
    class PreviewImage:  # type: ignore[no-redef]
        RETURN_TYPES = ("IMAGE",)
        OUTPUT_NODE = True

        def save_images(self, images, filename_prefix="ComfyUI", prompt=None, extra_pnginfo=None):
            return {"ui": {"images": []}}


class QQImageComparer(PreviewImage):
    """把两张图存成预览，交给前端 DOM 控件做滑动 / 点击对比。"""

    CATEGORY = "QQ/工具"
    FUNCTION = "compare_images"
    RETURN_TYPES = ("IMAGE",)
    RETURN_NAMES = ("图像",)
    DESCRIPTION = (
        "在同一节点里对比两张图：滑动模式鼠标左右移动揭开 B 图，点击模式点按切换。"
        "两侧都可以接一批图，用顶部标签挑选要对比的项。前端用 DOM 控件，兼容 Nodes 1.0 / 2.0。"
    )

    @classmethod
    def INPUT_TYPES(cls) -> dict[str, Any]:
        return {
            "required": {},
            "optional": {
                "image_a": ("IMAGE",),
                "image_b": ("IMAGE",),
            },
            "hidden": {
                "prompt": "PROMPT",
                "extra_pnginfo": "EXTRA_PNGINFO",
            },
        }

    def compare_images(
        self,
        image_a: Any = None,
        image_b: Any = None,
        filename_prefix: str = "qq.compare.",
        prompt: Any = None,
        extra_pnginfo: Any = None,
    ) -> dict[str, Any]:
        result: dict[str, Any] = {"ui": {"a_images": [], "b_images": []}}
        if image_a is not None and len(image_a) > 0:
            result["ui"]["a_images"] = self.save_images(
                image_a, filename_prefix, prompt, extra_pnginfo
            )["ui"]["images"]
        if image_b is not None and len(image_b) > 0:
            result["ui"]["b_images"] = self.save_images(
                image_b, filename_prefix, prompt, extra_pnginfo
            )["ui"]["images"]

        # 输出口沿用 A（没有 A 时用 B），方便 downstream 继续接图。
        result["result"] = (image_a if image_a is not None else image_b,)
        return result


NODE_CLASS_MAPPINGS = {"QQImageComparer": QQImageComparer}
NODE_DISPLAY_NAME_MAPPINGS = {"QQImageComparer": "QQ-图像对比"}
